/* duplicate an array (deep copy) */
struct cnfarray *cnfarrayDup(struct cnfarray *old) {
    int i;
    struct cnfarray *ar;
    if (old == NULL || old->nmemb == 0) {
        return cnfarrayNew(NULL);
